head.script:
scwin.openMenu = function(menuNm, url, menuCode, scopeId) {
    var tabObj = {
        closable: true,
        openAction: "exist",
        label: menuNm
    };
    var contObj = {
        frameMode: "wframePreload",
        scope: true,
        src: url,
        alwaysDraw: false,
        title: menuNm
    };
    var tabComp = $w.getComponentById(scopeId + "_tac_layout");
    tabComp.addTab(menuCode, tabObj, contObj);
    if (tabComp.getSelectedTabID() !== menuCode) {
        var tabIndex = tabComp.getTabIndex(menuCode);
        if (tabIndex) {
            tabComp.setSelectedTabIndex(tabIndex);
        }
    }
};
scwin.historyTitle1_onclick = function() {
    var scopeId = WebSquare.idCache[this.parentFrame].id;
    scwin.openMenu("mainTab1", "/sample/common_link/gridView_setColumnVisible_WESD-751_(WSQ-4801)_childTab.xml", "010001", scopeId);
};
scwin.checkVal = function() {
    return (document.getElementById('mf_tac_layout_contents_010001_body_tabControl1_contents_content2_body_gridView1_body_tbody') || document.getElementById('tac_layout_contents_010001_body_tabControl1_contents_content2_body_gridView1_body_tbody')).children[0].style.display != 'none';
};
